 1	final class Knapsack {
 2	    private static final int[] SAMPLE_VALUES = {1, 2, 3};
 3	    private static final int[] SAMPLE_WEIGHTS = {4, 5, 1};
 4	    private static final int SAMPLE_CAPACITY = 4;
 5	
 6	    private Knapsack() {
 7	    }
 8	
 9	    static int knapsack(int capacity, int[] values, int[] weights) {
10	        return new Solver(capacity, Item.from(values, weights)).solve();
11	    }
12	
13	    private static final class Solver {
14	        private final CapacityTable capacityTable;
15	        private final Item[] items;
16	
17	        private Solver(int capacity, Item[] items) {
18	            capacityTable = new CapacityTable(capacity);
19	            this.items = items;
20	        }
21	
22	        private int solve() {
23	            for (Item item : items) {
24	                include(item);
25	            }
26	            return capacityTable.maxValueAt(capacityTable.capacity());
27	        }
28	
29	        private void include(Item item) {
30	            for (int currentCapacity = capacityTable.capacity(); item.fitsWithin(currentCapacity); currentCapacity--) {
31	                capacityTable.setMaxValueAt(
32	                        currentCapacity,
33	                        bestValueForCapacity(currentCapacity, item)
34	                );
35	            }
36	        }
37	
38	        private int bestValueForCapacity(int currentCapacity, Item item) {
39	            int valueWithoutItem = capacityTable.maxValueAt(currentCapacity);
40	            int valueWithItem = item.valueIfIncluded(capacityTable, currentCapacity);
41	            return Math.max(valueWithoutItem, valueWithItem);
42	        }
43	    }
44	
45	    private static final class CapacityTable {
46	        private final int[] maxValueByCapacity;
47	
48	        private CapacityTable(int capacity) {
49	            maxValueByCapacity = new int[capacity + 1];
50	        }
51	
52	        private int capacity() {
53	            return maxValueByCapacity.length - 1;
54	        }
55	
56	        private int maxValueAt(int capacity) {
57	            return maxValueByCapacity[capacity];
58	        }
59	
60	        private void setMaxValueAt(int capacity, int value) {
61	            maxValueByCapacity[capacity] = value;
62	        }
63	    }
64	
65	    private static final class Item {
66	        private final int weight;
67	        private final int value;
68	
69	        private Item(int weight, int value) {
70	            this.weight = weight;
71	            this.value = value;
72	        }
73	
74	        private static Item[] from(int[] values, int[] weights) {
75	            Item[] items = new Item[weights.length];
76	
77	            for (int itemIndex = 0; itemIndex < weights.length; itemIndex++) {
78	                items[itemIndex] = new Item(weights[itemIndex], values[itemIndex]);
79	            }
80	            return items;
81	        }
82	
83	        private boolean fitsWithin(int capacity) {
84	            return weight <= capacity;
85	        }
86	
87	        private int valueIfIncluded(CapacityTable capacityTable, int capacity) {
88	            return capacityTable.maxValueAt(capacity - weight) + value;
89	        }
90	    }
91	
